import { test, expect } from '@playwright/test';

test.describe('Faceted Search', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display results based on selected filters', async ({ page }) => {
    await page.getByRole('button', { name: 'Filter by Category' }).click();
    await page.getByText('Electronics').click();

    const results = await page.getByRole('list', { name: 'Search Results' });
    await expect(results).toContainText('Electronics');
  });

  test('should update results when multiple filters are applied', async ({ page }) => {
    await page.getByRole('button', { name: 'Filter by Category' }).click();
    await page.getByText('Electronics').click();
    await page.getByRole('button', { name: 'Filter by Brand' }).click();
    await page.getByText('Brand A').click();

    const results = await page.getByRole('list', { name: 'Search Results' });
    await expect(results).toContainText('Brand A');
    await expect(results).toContainText('Electronics');
  });
});
